function solve() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
    const n = parseInt(input[0], 10);
    const m = parseInt(input[1], 10);
    const k = parseInt(input[2], 10);

    let ansX = 0;
    let ansY = 0;

    if (k < n) {
        ansX = k + 1;
        ansY = 1;
    } else {
        let remainingK = k - n;
        const count = Math.floor(remainingK / (m - 1));
        ansX = n - count;
        const mod = remainingK % (m - 1);
        if (count % 2 === 0) {
            ansY = 2 + mod;
        } else {
            ansY = m - mod;
        }
    }

    console.log(`${ansX} ${ansY}`);
}

solve();

